head.script:
///////// 1. 변수 및 선언 영역 /////////
// 원본 : ULDSTF05107.xml (W-Craft 변환본 + API 적용 개발 사본, 원본 ULDSTF05107.gfm 은 저장소에 없음)
/*
 * 화면 동작
 *  - 부모(ULDSTF05100 예비심사·ULDSTF05101 예비심사관리·ULDSTF05102 상장심사)가 넘긴 발행기관코드로
 *    그 발행기관의 종류주식 종목을 조회한다. 열리면 바로 조회하고, 종목명으로 다시 조회할 수 있다.
 *  - 행을 더블클릭하면 고른 종목을 부모에 돌려주고 닫는다(창 닫기 = 취소).
 * 업무 분석 : conversion/conversion-front/ui/ULDSTF05107/ULDSTF05107.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다. (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 파라미터 수신 → Enter 키 바인딩 → 종목명 칸 포커스 → 종목 목록 조회. (원본 scwin.init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 파라미터 수신 — 원본은 부모 컴포넌트(ibx_isurCd/txb_ISU_CD)를 직접 읽었다 (§1.2, §8 #1)
    //    secugrpId·mktTpCd·searchType 도 계약상 넘어오지만 조회 API 가 받지 않아 쓰지 않는다 (§10 #1)
    const param = $c.data.getParameter() ?? {};
    dma_search.set("isurCd", param.isurCd ?? "");

    // 2) 조회 영역 Enter 키 (규칙 22) — 원본 txb_Search_onkeydown(keyCode 13)
    $c.win.setEnterKeyEvent(grp_search, scwin.img_Search_onclick);

    // 3) 열리면 바로 조회
    txb_Search.focus();
    await scwin.selectList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_Search_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description [조회] — 종목명으로 다시 조회한다. (원본 img_Search_onclick — 원본 버튼에는 ev:onclick 이 없었다, §8 #3)
 * @returns
 * @hidden N
 */
scwin.img_Search_onclick = async function () {
    try {
        await scwin.selectList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.img_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_IsuInst_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 목록 더블클릭 — 고른 종목을 부모에 돌려주고 닫는다. (원본 grd_IsuInst_OnDblClick — §4)
 * @param {Number} rowIndex 행 번호
 * @param {Number} columnIndex 열 번호
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.returnIsu(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.grd_IsuInst_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 목록 조회 — GET select-list-kindstk(isurCd·isuNm) → dlt_listKindstkRes, 건수 표시. (원본 fn_list_sync — §5.1)
 * 원본은 쿼리스트링을 문자열로 이어 붙여 종목명을 인코딩하지 않았다 → dma_search 를 ref 로 넘겨 공통이 인코딩한다(§8 #4).
 * @returns
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectListKindstk",
        action : "/api/listing/common/pop/isu/select-list-kindstk",
        method : "get",
        ref : "dma_search",
        target : "dlt_listKindstkRes=body",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res?.skipped) return;   // 진행 중 조회가 있어 이번 호출은 건너뜀

    txb_TotCnt.setValue(dlt_listKindstkRes.getRowCount());
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.returnIsu
 * @author Inswave
 * @date 2026. 10. 29
 * @description 고른 종목을 반환 계약 키(camelCase)로 부모에 돌려주고 닫는다. 원본의 대문자 키(ISU_CD·DBCLICKYN 등)는 쓰지 않는다. (§1.2 반환 규약)
 * @param {Number} rowIndex 행 번호
 * @returns
 * @hidden N
 */
scwin.returnIsu = async function (rowIndex) {
    const row = dlt_listKindstkRes.getRowJSON(rowIndex);

    await $c.win.closePopup({
        isuCd : row.isuCd ?? "",            // AS-IS ISU_CD
        isuNm : row.isuNm ?? "",            // AS-IS ISU_NM
        isuEngNm : row.isuEngNm ?? "",      // AS-IS ISU_ENG_NM
        isurCd : row.isurCd ?? "",          // AS-IS ISUR_CD
        bzProcsNo : row.bzProcsNo ?? "",    // AS-IS BZPROCSNO — 신규상장에서 쓰는 값
        dbClickYn : "Y"                     // AS-IS DBCLICKYN
    });
};
